import type { ComparisonPair } from "@/lib/types";

// Source budgets do not cover the PNGs generated by image comparisons.
const IMAGE_CACHE_BYTES = 64 * 1024 * 1024;

function retainedImageBytes(pair: ComparisonPair): number {
  if (pair.result?.type !== "image") return 0;
  const { originalDataUrl, modifiedDataUrl, diffDataUrl } = pair.result.diff;
  // Account conservatively for two bytes per JS string character.
  return 2 * (originalDataUrl.length + modifiedDataUrl.length + diffDataUrl.length);
}

/** Evict least-recently visited image results, always keeping the visible pair. */
export function trimImageResults(
  pairs: ComparisonPair[],
  activeId: string,
  accessOrder: readonly string[],
  budget = IMAGE_CACHE_BYTES,
): ComparisonPair[] {
  let retained = pairs.reduce((total, pair) => total + retainedImageBytes(pair), 0);
  if (retained <= budget) return pairs;
  const candidates = pairs
    .filter((pair) => pair.modified.id !== activeId && pair.result?.type === "image")
    .sort((a, b) => accessOrder.indexOf(a.modified.id) - accessOrder.indexOf(b.modified.id));
  const evicted = new Set<string>();
  for (const pair of candidates) {
    if (retained <= budget) break;
    retained -= retainedImageBytes(pair);
    evicted.add(pair.modified.id);
  }
  if (!evicted.size) return pairs;
  return pairs.map((pair) => evicted.has(pair.modified.id)
    ? { ...pair, result: null, resultOptions: undefined }
    : pair);
}
